import {
  Minus,
  ChartTrendingDown as TrendingDown,
  ChartTrendingUp as TrendingUp,
} from "@nebutra/icons";
import { cn } from "../utils/cn";
import { Card, CardContent } from "./card";

export interface KpiCardProps {
  title: string;
  value: string | number | never;
  icon: React.ReactNode;
  trend?: {
    value: number;
    isPositive: boolean;
  };
  description?: string;
  className?: string;
}

export function KpiCard({ title, value, icon, trend, description, className }: KpiCardProps) {
  return (
    <Card className={cn("", className)}>
      <CardContent className="p-6">
        <div className="flex items-start justify-between">
          <div className="flex-1">
            <p className="text-sm font-medium text-muted-foreground">{title}</p>
            <p className="mt-2 text-3xl font-bold text-foreground">
              {typeof value === "number" ? value.toLocaleString() : value}
            </p>

            {trend && (
              <div className="mt-2 flex items-center gap-1">
                {trend.isPositive ? (
                  <>
                    <TrendingUp className="size-4 text-green-600" />
                    <span className="text-sm font-medium text-green-600">
                      +{Math.abs(trend.value)}%
                    </span>
                  </>
                ) : trend.value === 0 ? (
                  <>
                    <Minus className="size-4 text-muted-foreground" />
                    <span className="text-sm font-medium text-muted-foreground">0%</span>
                  </>
                ) : (
                  <>
                    <TrendingDown className="size-4 text-red-600" />
                    <span className="text-sm font-medium text-red-600">{trend.value}%</span>
                  </>
                )}
                <span className="text-sm text-muted-foreground">vs last week</span>
              </div>
            )}

            {description && <p className="mt-1 text-sm text-muted-foreground">{description}</p>}
          </div>

          <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-[var(--radius-lg)] bg-muted">
            {icon}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import * as React from "react";
import { cn } from "../utils/cn";

const Card = ({
  className,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    ref={ref}
    className={cn(
      "rounded-[var(--radius-lg)] border border-border bg-card text-card-foreground shadow-sm",
      className,
    )}
    {...props}
  />
);
Card.displayName = "Card";

const CardHeader = ({
  className,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div ref={ref} className={cn("flex flex-col space-y-1.5 p-6", className)} {...props} />
);
CardHeader.displayName = "CardHeader";

const CardTitle = ({
  className,
  children,
  ref,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement> & {
  ref?: React.Ref<HTMLHeadingElement> | undefined;
}) => (
  <h3
    ref={ref}
    className={cn("text-2xl font-semibold leading-none tracking-tight", className)}
    {...props}
  >
    {children}
  </h3>
);
CardTitle.displayName = "CardTitle";

export interface CardDescriptionProps
  extends React.HTMLAttributes<HTMLParagraphElement | HTMLDivElement> {
  as?: React.ElementType;
}

const CardDescription = ({
  className,
  as: Tag = "p",
  ref,
  ...props
}: CardDescriptionProps & {
  ref?: React.Ref<HTMLParagraphElement | HTMLDivElement> | undefined;
}) => {
  return React.createElement(Tag, {
    ref,
    className: cn("text-sm text-muted-foreground", className),
    ...props,
  });
};
CardDescription.displayName = "CardDescription";

const CardContent = ({
  className,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div ref={ref} className={cn("p-6 pt-0", className)} {...props} />
);
CardContent.displayName = "CardContent";

const CardFooter = ({
  className,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div ref={ref} className={cn("flex items-center p-6 pt-0", className)} {...props} />
);
CardFooter.displayName = "CardFooter";

export { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };
